#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

bool helper(int n, int left, int right, int j, vector<int>& a){
    for(auto i : a){
        int ii = min(left, i) + max(0, right - n + i);
        int jj = min(right, n - i + 1) + max(0, left - i + 1);
        
        bool x = j <= i && ii == (i - 1) / 2;
        bool y = j >= i && jj == (n - i) / 2;
        
        if(!x && !y) return false;
    }
    
    return true;
}

int main() {
    int t;
    cin >> t;
    
    while(t--){
        int n;
        cin >> n;
        
        vector<vector<int>> a(n+1);
        vector<int> dp(n + 1, 0), t1(n + 1, 0);
        
        for(int i = 1; i <= n; i++){
            int x;
            cin >> x;
            a[x].push_back(i);
        }
        
        dp[0] = 1;
        
        for(int i = 1; i<= n; i++){
            for(int j = 0; j <= n; j++) t1[j] = 0;
            
            for(int j = 0; j < i; j++){
                if(dp[j] == 0) continue;
                
                int right = i - j - 1;
                
                if(helper(n, j, right, j+1, a[i])){
                    t1[j+1] += dp[j];
                    
                    if(t1[j+1] >= MOD) t1[j+1] -= MOD;
                }
                
                if(i < n && helper(n, j, right, n-right, a[i])){
                    t1[j] += dp[j];
                    
                    if(t1[j] >= MOD) t1[j] -= MOD;
                }
            }
            
            dp.swap(t1);
        }
        
        int ans = 0;
        for(int i = 0; i <= n; i++){
            ans += dp[i];
            
            if(ans >= MOD) ans -= MOD;
        }
        
        cout << ans << "\n";
    }
}
